enum_strings.cpp.src:
#include <cstdint>
#include <iostream>
#include <optional>
#include <string_view>

enum class Light : std::uint8_t { off, dim, bright };

std::string_view to_string(Light l) {
    switch (l) {
        case Light::off: return "off";
        case Light::dim: return "dim";
        case Light::bright: return "bright";
    }
    return "?";
}

constexpr Light all_lights[]{Light::off, Light::dim, Light::bright};

std::optional<Light> light_from(std::string_view text) {
    for (Light l : all_lights) {
        if (to_string(l) == text) {
            return l;
        }
    }
    return std::nullopt;
}

int main() {
    Light l{Light::dim};
    std::cout << to_string(l) << " is number " << static_cast<int>(l) << '\n';
    std::cout << "size: " << sizeof(Light) << " byte\n";
    for (std::string_view word : {"bright", "purple"}) {
        if (std::optional<Light> got{light_from(word)}) {
            std::cout << word << " -> Light::" << to_string(*got) << '\n';
        } else {
            std::cout << word << " -> not a light\n";
        }
    }
}

