#include <algorithm>
#include <cmath>
#include <iostream>
#include <limits>

bool nearly_equal(double x, double y, double rel = 1e-9) {
    return std::abs(x - y) <= rel * std::max(std::abs(x), std::abs(y));
}

int main() {
    std::cout << "epsilon: " << std::numeric_limits<double>::epsilon() << '\n';
    double total{0.0};
    for (int i{0}; i < 10; ++i) {
        total += 0.1;
    }
    std::cout << "ten 0.1s == 1.0? " << (total == 1.0) << '\n';
    std::cout << "nearly 1.0?      " << nearly_equal(total, 1.0) << '\n';
    std::cout << "nearly 1.1?      " << nearly_equal(total, 1.1) << '\n';
}

