std::optional<int> parse_digit(char c) {
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    return std::nullopt;
}

int main() {
    std::string code{"7x"};
    int first{parse_digit(code[0]).value_or(0)};
    int second{*parse_digit(code[1])};
    std::cout << first + second << '\n';
}

